246	    /**
247	     * Assign the joining owner and an existing household member the same stable
248	     * household identifier. The identifier is derived deterministically from the
249	     * shared household key (last name + address, normalised), so every owner in a
250	     * household resolves to the same value; the existing member is updated when it
251	     * does not already carry it.
252	     *
253	     * @param owner    the owner being created
254	     * @param existing an existing owner in the same household
255	     */
256	    private void joinHousehold(Owner owner, Owner existing) {
257	        String householdId = UUID
258	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
259	        owner.setHouseholdId(householdId);
260	        if (!householdId.equals(existing.getHouseholdId())) {
