275	    private String nextCustomerCode(String lastName) {
276	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
277	        long sequence = this.clinicService.findAllOwners().size() + 1L;
278	        return String.format("%s-%04d", last3, sequence);
