281	    /**
282	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
283	     * code when present, otherwise assume country code '+61' and drop a single
284	     * leading '0' from the national digits. Spaces, dashes and brackets are
285	     * stripped. The result must contain 8 to 15 digits after the '+'.
286	     *
287	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
288	     *         input cannot form a valid E.164 number.
289	     */
290	    private static String toE164(String raw) {
291	        if (raw == null) {
292	            return null;
293	        }
294	        String cleaned = raw.replaceAll("[\\s()-]", "");
295	        String digits;
296	        if (cleaned.startsWith("+")) {
297	            digits = cleaned.substring(1);
298	        } else {
299	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
300	            digits = "61" + national;
301	        }
302	        if (!digits.matches("\\d{8,15}")) {
303	            return null;
304	        }
305	        return "+" + digits;
306	    }
